                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.LargeIconFilename = AssetLinkBinaryTranslation.Instance.Parse<FalloutNVTextureAssetType>(reader: frame.SpawnWithLength(contentLength));
                    return (int)MiscItem_FieldIndex.LargeIconFilename;
                }
                case RecordTypeInts.MICO:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.SmallIconFilename = AssetLinkBinaryTranslation.Instance.Parse<FalloutNVTextureAssetType>(reader: frame.SpawnWithLength(contentLength));
                    return (int)MiscItem_FieldIndex.SmallIconFilename;
                }
                case RecordTypeInts.SCRI:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.Script.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)MiscItem_FieldIndex.Script;
                }
                case RecordTypeInts.DEST:
                case RecordTypeInts.DSTD:
                {
                    item.Destructible = Mutagen.Bethesda.FalloutNV.Destructible.CreateFromBinary(
